// Draws a brand board page from MiroMiro's Extract Brand result.
const b = $input.first().json
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]))
// No ?url= or the site could not be read: show a short page that says why.
const asked = $('Open Brand Board in Browser').first().json.query?.url
if (!asked || b.error || !b.colors) {
  const why = !asked ? 'Add the website to the address, for example <code>?url=stripe.com</code>.' : 'MiroMiro could not read ' + esc(asked) + ': ' + esc(b.error?.message || b.error || 'no brand found') + '.'
  return [{ json: { html: '<!doctype html><meta charset="utf-8"><title>Brand board</title><body style="font-family:system-ui;padding:40px;color:#18181b"><h1>Brand board</h1><p>' + why + '</p></body>' } }]
}
const hex = (c) => String(c || '').toLowerCase()
// Black or white text, whichever reads better on the color.
const ink = (c) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex(c).replace('#', '').padEnd(6, '0'))
  if (!m) return '#111'
  const n = parseInt(m[1], 16)
  const lum = (0.299 * (n >> 16) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255)) / 255
  return lum > 0.6 ? '#111' : '#fff'
}
const host = String(b.url || '').replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '')
const colors = b.colors || {}
const names = b.colorNames || {}
const roles = ['primary', 'accent', 'text', 'background'].filter((r) => colors[r])
const palette = (b.palette || []).slice(0, 12)
const fonts = b.typography || {}
const fontList = [fonts.primary, fonts.mono].filter(Boolean)
const socials = (b.socials || []).slice(0, 6)
const logo = (b.logos || []).find((l) => /\.svg/i.test(l.url)) || (b.logos || [])[0] || (b.logo ? { url: b.logo } : null)

const roleCard = (r) => `
  <div class="role" style="background:${esc(colors[r])};color:${ink(colors[r])}">
    <span class="role-name">${esc(r)}</span>
    <span class="role-hex">${esc(hex(colors[r]))}</span>
    <span class="role-label">${esc(names[r] || '')}</span>
  </div>`
const swatch = (p) => `
  <div class="swatch">
    <div class="chip" style="background:${esc(p.color)}"></div>
    <div class="meta"><b>${esc(p.name)}</b><span>${esc(hex(p.color))}</span></div>
  </div>`

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(host)} brand board</title>
<style>
  *{box-sizing:border-box;margin:0}
  body{font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;background:#f4f4f5;color:#18181b;padding:40px 20px}
  .wrap{max-width:1040px;margin:0 auto}
  header{display:flex;align-items:center;gap:18px;background:#fff;border-radius:24px;padding:24px 28px;box-shadow:0 1px 2px rgba(0,0,0,.05)}
  header img{width:64px;height:64px;object-fit:contain;border-radius:14px;background:#fafafa;padding:8px;border:1px solid #eee}
  header h1{font-size:28px;letter-spacing:-.02em}
  header p{color:#71717a;font-size:14px;margin-top:4px;max-width:640px}
  h2{font-size:13px;text-transform:uppercase;letter-spacing:.12em;color:#71717a;margin:34px 4px 14px}
  .roles{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
  .role{border-radius:22px;min-height:170px;padding:20px;display:flex;flex-direction:column;justify-content:flex-end;gap:4px;border:1px solid rgba(0,0,0,.06)}
  .role-name{font-size:12px;text-transform:uppercase;letter-spacing:.1em;opacity:.8}
  .role-hex{font-size:26px;font-weight:600;letter-spacing:-.01em}
  .role-label{font-size:13px;opacity:.8}
  .palette{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}
  .swatch{background:#fff;border-radius:18px;padding:8px;border:1px solid #eee}
  .chip{height:78px;border-radius:12px;border:1px solid rgba(0,0,0,.06)}
  .meta{padding:8px 4px 2px;display:flex;flex-direction:column;gap:2px;font-size:12.5px}
  .meta span{color:#71717a;font-family:ui-monospace,Menlo,monospace}
  .fonts{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
  .font{background:#fff;border-radius:22px;padding:24px;border:1px solid #eee}
  .font .sample{font-size:44px;letter-spacing:-.02em;line-height:1.1;margin:10px 0}
  .font small{color:#71717a}
  .note{background:#fff;border-radius:18px;padding:16px 20px;border:1px solid #eee;color:#3f3f46;font-size:14px;line-height:1.6}
  .socials{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
  .socials a{background:#18181b;color:#fff;text-decoration:none;font-size:12.5px;padding:6px 12px;border-radius:999px}
  footer{margin-top:30px;text-align:center;color:#a1a1aa;font-size:12.5px}
  footer a{color:#6366f1;text-decoration:none}
  @media(max-width:760px){.roles{grid-template-columns:repeat(2,1fr)}.palette{grid-template-columns:repeat(3,1fr)}.fonts{grid-template-columns:1fr}}
</style></head>
<body><div class="wrap">
  <header>
    ${logo ? `<img src="${esc(logo.url)}" alt="">` : ''}
    <div><h1>${esc(host)}</h1><p>${esc(b.description || b.title || '')}</p></div>
  </header>

  <h2>Brand colors</h2>
  <div class="roles">${roles.map(roleCard).join('')}</div>

  ${palette.length ? `<h2>Palette</h2><div class="palette">${palette.map(swatch).join('')}</div>` : ''}

  ${fontList.length ? `<h2>Typography</h2><div class="fonts">${fontList.map((f, i) => `
    <div class="font"><small>${i === 0 && f === fonts.primary ? 'Primary' : 'Mono'}</small>
      <div class="sample" style="font-family:'${esc(f)}',${i === 0 && f === fonts.primary ? 'Inter,system-ui,sans-serif' : 'ui-monospace,monospace'}">Aa Bb Cc 123</div>
      <b>${esc(f)}</b></div>`).join('')}</div>` : ''}

  <h2>How sure is this</h2>
  <div class="note">${esc(b.signals && b.signals.explanation ? b.signals.explanation : '')}
    ${socials.length ? `<div class="socials">${socials.map((s) => `<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.platform)} ${esc(s.handle || '')}</a>`).join('')}</div>` : ''}
  </div>

  <footer>Built with n8n and <a href="https://miromiro.app/api" target="_blank" rel="noopener">MiroMiro</a> from the live site</footer>
</div></body></html>`

return [{ json: { html } }]
